331	    76	    public Object command(String... args) {
332	    77	        if (!enabled) throw new IllegalStateException("redis disabled");
333	    78	        try (Socket socket = new Socket()) {
334	    79	            socket.connect(new InetSocketAddress(host, port), timeoutMs);
335	    80	            socket.setSoTimeout(timeoutMs);
336	    81	            OutputStream out = new BufferedOutputStream(socket.getOutputStream());
337	    82	            StringBuilder sb = new StringBuilder("*").append(args.length).append("\r\n");
338	    83	            for (String a : args) {
339	    84	                byte[] b = a.getBytes(StandardCharsets.UTF_8);
340	    85	                sb.append("$").append(b.length).append("\r\n").append(a).append("\r\n");
341	    86	            }
342	    87	            out.write(sb.toString().getBytes(StandardCharsets.UTF_8));
343	    88	            out.flush();
344	    89	            InputStream in = new BufferedInputStream(socket.getInputStream());
345	    90	            return read(in);
346	    91	        } catch (Exception e) {
347	    92	            throw new IllegalStateException("redis command failed: " + e.getMessage(), e);
348	    93	        }
