351	    96	    private Object read(InputStream in) throws Exception {
352	    97	        int type = in.read();
353	    98	        if (type < 0) throw new IllegalStateException("empty redis response");
354	    99	        String line = readLine(in);
355	   100	        switch (type) {
356	   101	            case '+': return line;
357	   102	            case '-': throw new IllegalStateException("redis error: " + line);
358	   103	            case ':': return Long.parseLong(line);
359	   104	            case '$': {
360	   105	                int len = Integer.parseInt(line);
361	   106	                if (len < 0) return null;
362	   107	                byte[] buf = in.readNBytes(len);
363	   108	                readLine(in);
364	   109	                return new String(buf, StandardCharsets.UTF_8);
365	   110	            }
366	   111	            case '*': {
367	   112	                int n = Integer.parseInt(line);
368	   113	                if (n < 0) return null;
369	   114	                Object[] arr = new Object[n];
370	   115	                for (int i = 0; i < n; i++) arr[i] = read(in);
371	   116	                return arr;
372	   117	            }
373	   118	            default: throw new IllegalStateException("unknown redis reply type " + type);
374	   119	        }
375	   120	    }
