377	   122	    private String readLine(InputStream in) throws Exception {
378	   123	        StringBuilder sb = new StringBuilder();
379	   124	        int c;
380	   125	        while ((c = in.read()) != -1) {
381	   126	            if (c == '\r') {
382	   127	                int n = in.read();
383	   128	                if (n == '\n') break;
384	   129	                sb.append((char) c).append((char) n);
385	   130	            } else {
386	   131	                sb.append((char) c);
387	   132	            }
388	   133	        }
389	   134	        return sb.toString();
390	   135	    }
