41	    40	    public Map<String, Object> listDishes(int page, int size, String search, String category, String status) {
42	    41	        Util.validatePage(page, size);
43	    42	        if (category != null && !category.isBlank() && !Util.CATEGORIES.contains(category)) {
44	    43	            throw Api.error(400, "VALIDATION_CATEGORY", "Invalid category");
45	    44	        }
46	    45	        if (status != null && !status.isBlank() && !List.of("ON_SHELF", "OFF_SHELF").contains(status)) {
47	    46	            throw Api.error(400, "VALIDATION_INVALID", "Invalid status");
48	    47	        }
49	    48	        if (search != null && search.length() > 50) throw Api.error(400, "VALIDATION_SEARCH_LENGTH", "Search too long");
50	    49	        StringBuilder where = new StringBuilder(" WHERE 1=1");
51	    50	        List<Object> args = new ArrayList<>();
52	    51	        if (search != null && !search.isBlank()) {
53	    52	            where.append(" AND (name LIKE ? ESCAPE '\\\\' OR description LIKE ? ESCAPE '\\\\')");
54	    53	            String p = "%" + Util.escapeLike(search.trim()) + "%";
55	    54	            args.add(p);
56	    55	            args.add(p);
57	    56	        }
58	    57	        if (category != null && !category.isBlank()) { where.append(" AND category=?"); args.add(category); }
59	    58	        if (status != null && !status.isBlank()) { where.append(" AND status=?"); args.add(status); }
60	    59	        Long total = jdbc.queryForObject("SELECT COUNT(*) FROM dishes" + where, Long.class, args.toArray());
61	    60	        args.add(size);
62	    61	        args.add((page - 1) * size);
63	    62	        List<Map<String, Object>> rows = jdbc.queryForList(
64	    63	                "SELECT id,name,description,price_cents,category,protein,allergens,spice_level,image_url,status FROM dishes"
65	    64	                        + where + " ORDER BY id LIMIT ? OFFSET ?", args.toArray());
66	    65	        List<Map<String, Object>> items = new ArrayList<>();
67	    66	        for (Map<String, Object> r : rows) items.add(dishView(r));
68	    67	        Map<String, Object> data = new LinkedHashMap<>();
69	    68	        data.put("items", items);
70	    69	        data.put("page", page);
71	    70	        data.put("size", size);
72	    71	        data.put("total", total == null ? 0 : total);
73	    72	        return data;
74	    73	    }
