139	   138	    public Map<String, Object> uploadImage(long dishId, MultipartFile file) {
140	   139	        jdbc.queryForObject("SELECT id FROM dishes WHERE id=?", Long.class, dishId);
141	   140	        if (file == null || file.isEmpty()) throw Api.error(400, "VALIDATION_IMAGE", "Image file is required");
142	   141	        if (file.getSize() > 5 * 1024 * 1024) throw Api.error(400, "VALIDATION_IMAGE", "Image must be at most 5MB");
143	   142	        try {
144	   143	            byte[] bytes = file.getBytes();
145	   144	            String ext = magicExt(bytes);
146	   145	            if (ext == null) throw Api.error(400, "VALIDATION_IMAGE", "Only jpg, png or webp images are allowed");
147	   146	            Path dir = Paths.get("./uploads/images");
148	   147	            Files.createDirectories(dir);
149	   148	            String name = UUID.randomUUID() + "." + ext;
150	   149	            Files.write(dir.resolve(name), bytes);
151	   150	            String url = "/images/" + name;
152	   151	            jdbc.update("UPDATE dishes SET image_url=? WHERE id=?", url, dishId);
153	   152	            audit.log("DISH_IMAGE", "DISH", String.valueOf(dishId), null, Map.of("imageUrl", url), null);
154	   153	            menuService.invalidate();
155	   154	            Map<String, Object> data = new LinkedHashMap<>();
156	   155	            data.put("imageUrl", url);
157	   156	            return data;
158	   157	        } catch (IOException e) {
159	   158	            throw Api.error(400, "VALIDATION_IMAGE", "Failed to store image");
160	   159	        }
161	   160	    }
