207	   206	    public List<Map<String, Object>> dailyMenu(String dateStr) {
208	   207	        LocalDate date = dateStr == null || dateStr.isBlank() ? RequestContext.today().plusDays(1)
209	   208	                : Util.parseDate(dateStr, "VALIDATION_INVALID");
210	   209	        List<Map<String, Object>> rows = jdbc.queryForList(
211	   210	                "SELECT m.dish_id,d.name,s.total_qty,s.reserved_qty,s.sold_qty,s.inventory_mode,m.publish_status "
212	   211	                        + "FROM daily_menu m JOIN dishes d ON d.id=m.dish_id "
213	   212	                        + "LEFT JOIN dish_daily_stock s ON s.dish_id=m.dish_id AND s.serve_date=m.serve_date "
214	   213	                        + "WHERE m.serve_date=? ORDER BY m.dish_id", date);
215	   214	        List<Map<String, Object>> out = new ArrayList<>();
216	   215	        for (Map<String, Object> r : rows) {
217	   216	            int total = Util.intVal(r.get("total_qty"));
218	   217	            int reserved = Util.intVal(r.get("reserved_qty"));
219	   218	            int sold = Util.intVal(r.get("sold_qty"));
220	   219	            int available = Math.max(0, total - reserved - sold);
221	   220	            Map<String, Object> m = new LinkedHashMap<>();
222	   221	            m.put("dishId", r.get("dish_id"));
223	   222	            m.put("dishName", r.get("name"));
224	   223	            m.put("totalQty", total);
225	   224	            m.put("reservedQty", reserved);
226	   225	            m.put("soldQty", sold);
227	   226	            m.put("available", available);
228	   227	            m.put("lowStock", available <= 3);
229	   228	            m.put("inventoryMode", r.get("inventory_mode") == null ? "DB_ATOMIC" : r.get("inventory_mode"));
230	   229	            m.put("published", "PUBLISHED".equals(r.get("publish_status")));
231	   230	            out.add(m);
232	   231	        }
233	   232	        return out;
234	   233	    }
