236	   235	    @Transactional
237	   236	    public Map<String, Object> saveDailyMenu(Dtos.DailyMenuReq req) {
238	   237	        if (req.serveDate() == null || req.serveDate().isBlank()) {
239	   238	            throw Api.error(400, "VALIDATION_INVALID", "serveDate is required");
240	   239	        }
241	   240	        LocalDate date = Util.parseDate(req.serveDate(), "VALIDATION_INVALID");
242	   241	        if (req.items() == null || req.items().isEmpty()) {
243	   242	            throw Api.error(400, "VALIDATION_INVALID", "items are required");
244	   243	        }
245	   244	        requireReason(req.reason());
246	   245	        List<Map<String, Object>> before = dailyMenu(date.toString());
247	   246	        for (Dtos.DailyMenuItem item : req.items()) {
248	   247	            if (item.dishId() == null) throw Api.error(400, "VALIDATION_INVALID", "dishId is required");
249	   248	            jdbc.queryForObject("SELECT id FROM dishes WHERE id=?", Long.class, item.dishId());
250	   249	            int total = item.totalQty() == null ? (req.totalQty() == null ? 0 : req.totalQty()) : item.totalQty();
251	   250	            if (total < 0) throw Api.error(400, "VALIDATION_INVALID", "totalQty must be >= 0");
252	   251	            String publish = Boolean.FALSE.equals(item.published()) ? "DRAFT" : "PUBLISHED";
253	   252	            jdbc.update("INSERT INTO daily_menu(dish_id,serve_date,publish_status) VALUES (?,?,?) "
254	   253	                            + "ON DUPLICATE KEY UPDATE publish_status=VALUES(publish_status)",
255	   254	                    item.dishId(), date, publish);
256	   255	            String mode = item.inventoryMode() == null ? "DB_ATOMIC" : item.inventoryMode();
257	   256	            if (!List.of("DB_ATOMIC", "REDIS_PREALLOC").contains(mode)) {
258	   257	                throw Api.error(400, "VALIDATION_INVALID", "Invalid inventoryMode");
259	   258	            }
260	   259	            List<Map<String, Object>> stock = jdbc.queryForList(
261	   260	                    "SELECT reserved_qty+sold_qty AS used FROM dish_daily_stock WHERE dish_id=? AND serve_date=?",
262	   261	                    item.dishId(), date);
263	   262	            if (stock.isEmpty()) {
264	   263	                jdbc.update("INSERT INTO dish_daily_stock(dish_id,serve_date,total_qty,inventory_mode) VALUES (?,?,?,?)",
265	   264	                        item.dishId(), date, total, mode);
266	   265	            } else {
267	   266	                int used = Util.intVal(stock.get(0).get("used"));
268	   267	                if (total < used) throw Api.error(409, "STOCK_INSUFFICIENT", "totalQty cannot be lower than reserved + sold");
269	   268	                jdbc.update("UPDATE dish_daily_stock SET total_qty=?, inventory_mode=?, version=version+1 "
270	   269	                        + "WHERE dish_id=? AND serve_date=?", total, mode, item.dishId(), date);
271	   270	            }
272	   271	        }
273	   272	        List<Map<String, Object>> after = dailyMenu(date.toString());
274	   273	        audit.log("DAILY_MENU_UPDATE", "DAILY_MENU", date.toString(), before, after, req.reason());
275	   274	        menuService.invalidate();
276	   275	        Map<String, Object> data = new LinkedHashMap<>();
277	   276	        data.put("serveDate", date.toString());
278	   277	        data.put("items", after);
279	   278	        return data;
280	   279	    }
