282	   281	    @Transactional
283	   282	    public Map<String, Object> updateStock(String serveDate, long dishId, Dtos.StockReq req) {
284	   283	        requireReason(req.reason());
285	   284	        if (req.totalQty() == null || req.totalQty() < 0) {
286	   285	            throw Api.error(400, "VALIDATION_INVALID", "totalQty must be >= 0");
287	   286	        }
288	   287	        LocalDate date = Util.parseDate(serveDate, "VALIDATION_INVALID");
289	   288	        Map<String, Object> before = jdbc.queryForMap(
290	   289	                "SELECT total_qty, reserved_qty, sold_qty FROM dish_daily_stock WHERE dish_id=? AND serve_date=?", dishId, date);
291	   290	        int n = jdbc.update("UPDATE dish_daily_stock SET total_qty=?, version=version+1 "
292	   291	                        + "WHERE dish_id=? AND serve_date=? AND ?>=reserved_qty+sold_qty",
293	   292	                req.totalQty(), dishId, date, req.totalQty());
294	   293	        if (n == 0) throw Api.error(409, "STOCK_INSUFFICIENT", "totalQty cannot be lower than reserved + sold");
295	   294	        int available = inventory.available(dishId, date);
296	   295	        Map<String, Object> after = Map.of("totalQty", req.totalQty(), "available", available);
297	   296	        audit.log("STOCK_UPDATE", "STOCK", dishId + ":" + date, before, after, req.reason());
298	   297	        menuService.invalidate();
299	   298	        Map<String, Object> data = new LinkedHashMap<>();
300	   299	        data.put("dishId", dishId);
301	   300	        data.put("serveDate", date.toString());
302	   301	        data.put("totalQty", req.totalQty());
303	   302	        data.put("available", available);
304	   303	        return data;
305	   304	    }
