357	   356	    public Map<String, Object> listOrders(int page, int size, String status, String dateStr) {
358	   357	        Util.validatePage(page, size);
359	   358	        StringBuilder where = new StringBuilder(" WHERE 1=1");
360	   359	        List<Object> args = new ArrayList<>();
361	   360	        if (status != null && !status.isBlank()) {
362	   361	            if (!Util.ORDER_STATUSES.contains(status)) throw Api.error(400, "VALIDATION_INVALID", "Invalid status");
363	   362	            where.append(" AND status=?");
364	   363	            args.add(status);
