91	    90	                for (Candidate c : chosen) reasons.add(reasonFor(c));
92	    91	            }
93	    92	            Map<String, Object> meta = new LinkedHashMap<>();
94	    93	            meta.put("fallback", fallback);
95	    94	            meta.put("model", model);
96	    95	            meta.put("sessionId", sessionId);
