135	   134	        }
136	   135	        Set<Long> recent = new HashSet<>();
137	   136	        for (Map<String, Object> r : jdbc.queryForList(
138	   137	                "SELECT DISTINCT oi.dish_id FROM order_items oi JOIN orders o ON o.id=oi.order_id "
139	   138	                        + "WHERE o.user_id=? AND o.status<>'Cancelled' AND o.created_at>=NOW(3)-INTERVAL 7 DAY", userId)) {
140	   139	            recent.add(((Number) r.get("dish_id")).longValue());
141	   140	        }
