186	   185	    private List<Candidate> tryLlm(String prompt, List<Candidate> candidates, List<String> reasons) {
187	   186	        if (candidates.isEmpty()) return null;
188	   187	        try {
189	   188	            StringBuilder list = new StringBuilder();
190	   189	            for (Candidate c : candidates) {
191	   190	                list.append(c.dishId()).append(": ").append(c.name()).append(" (").append(c.category())
192	   191	                        .append(", ¥").append(c.price() / 100).append(".").append(String.format("%02d", c.price() % 100)).append(")\n");
193	   192	            }
194	   193	            String userMsg = "User request: " + prompt + "\nCandidate dishes (id: name):\n" + list
195	   194	                    + "\nReturn ONLY a JSON array like [{\"dishId\":1,\"reason\":\"...\"}] using only candidate ids.";
196	   195	            Map<String, Object> body = new LinkedHashMap<>();
197	   196	            body.put("model", llmModel);
198	   197	            body.put("temperature", 0.3);
199	   198	            body.put("max_tokens", 500);
200	   199	            body.put("messages", List.of(
201	   200	                    Map.of("role", "system", "content", "You are a meal recommendation assistant. Only choose from the supplied candidate ids."),
202	   201	                    Map.of("role", "user", "content", userMsg)));
203	   202	            HttpClient client = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(3)).build();
204	   203	            HttpRequest request = HttpRequest.newBuilder(URI.create(llmBase.replaceAll("/$", "") + "/chat/completions"))
205	   204	                    .timeout(Duration.ofSeconds(8))
206	   205	                    .header("Authorization", "Bearer " + llmKey)
207	   206	                    .header("Content-Type", "application/json")
208	   207	                    .POST(HttpRequest.BodyPublishers.ofString(Util.json(body)))
209	   208	                    .build();
210	   209	            HttpResponse<String> resp = client.send(request, HttpResponse.BodyHandlers.ofString());
211	   210	            if (resp.statusCode() / 100 != 2) return null;
212	   211	            Map<String, Object> root = Util.parseMap(resp.body());
213	   212	            List<Map<String, Object>> choices = (List<Map<String, Object>>) root.get("choices");
214	   213	            if (choices == null || choices.isEmpty()) return null;
215	   214	            Map<String, Object> msg = (Map<String, Object>) choices.get(0).get("message");
216	   215	            String content = String.valueOf(msg.get("content"));
217	   216	            String json = content.substring(content.indexOf('['), content.lastIndexOf(']') + 1);
218	   217	            List<Map<String, Object>> parsed = Util.parseListOfMaps(json);
219	   218	            Map<Long, Candidate> byId = new LinkedHashMap<>();
220	   219	            for (Candidate c : candidates) byId.put(c.dishId(), c);
221	   220	            List<Candidate> chosen = new ArrayList<>();
222	   221	            for (Map<String, Object> p : parsed) {
223	   222	                long id = Util.cents(p.get("dishId"));
224	   223	                Candidate c = byId.get(id);
225	   224	                if (c != null && !chosen.contains(c)) {
226	   225	                    chosen.add(c);
227	   226	                    String reason = String.valueOf(p.get("reason"));
228	   227	                    reasons.add(reason.length() > 200 ? reason.substring(0, 200) : reason);
229	   228	                }
230	   229	            }
231	   230	            return chosen.isEmpty() ? null : chosen.stream().limit(5).toList();
232	   231	        } catch (Exception e) {
233	   232	            log.warn("LLM call failed, falling back to rules: {}", e.getMessage());
234	   233	            return null;
235	   234	        }
